SELECT 
FROM qa_file
WHERE owner_id = #{ownerId}
  AND idempotency_key = #{idempotencyKey}
  AND deleted_at IS NULL

SELECT 
FROM qa_file
WHERE public_id = #{id}
  AND owner_id = #{ownerId}
  AND conversation_id = #{conversationId}
  AND deleted_at IS NULL

SELECT 
FROM qa_file
WHERE owner_id = #{ownerId}
  AND conversation_id = #{conversationId}
  AND deleted_at IS NULL
ORDER BY created_at ASC, public_id ASC
LIMIT #{limit}

mapper.update:
UPDATE qa_file
SET status = #{status}, updated_at = #{updatedAt}
WHERE public_id = #{id}
  AND deleted_at IS NULL

UPDATE qa_file
SET status = 'DELETE_PENDING', updated_at = #{deletedAt}, deleted_at = #{deletedAt}
WHERE public_id = #{id}
  AND owner_id = #{ownerId}
  AND conversation_id = #{conversationId}
  AND deleted_at IS NULL
